	function upgradeTranslation () {
		init(true);				
		//1.0 has no upgrades
		if (gCurVersion  == CODEVERSION) {
			message("TRANSLATE: latest version ("+gCurVersion+") is installed")
		} else {
			upgraded = false
			if (gCurVersion == "0.9") {
				upgrade09_to_10();
				gCurVersion = "1.0";
				upgraded = true
			}
			if (gCurVersion == "1.0") {
				upgrade10_to_11();
				gCurVersion = "1.1";
				upgraded = true
			}
			if (gCurVersion == "1.1") {
				upgrade11_to_12();
				gCurVersion = "1.2";
				upgraded = true
			}
			if (upgraded) {
				updTranslInfo(gCurrentLang, gLanguages
					 ,CODEVERSION,curDateStr());	
				message("TRANSLATE: latest version ("+CODEVERSION+") is now installed")
			} else {
			error("\nTRANSLATE: unknown version ("+gCurVersion+").\n"
					+"Please contact support\n");
			}
		}			
	}

			//scripts to handle translation of model
				var CODEVERSION = '1.5'
				var gLogNote = "LOG";
				var gParams={}
			// Translation
				var gTranslInforegexp =/TRANSLATION\{([^}]*)\}/;
				var translation = false
				var NOTESSTARTTAG = '[<tag>[';
				var NOTESENDTAG = ']<tag>]';
				var CURRENTLANG = "currentLang"
				var VERSION = "version"
				var LASTSYNC = "lastSync"
				var LANGUAGES = "languages"
				var DEEPLAUTHKEY = "DEEPLAuthKey"

				var logInitialized = false;

			// message
				var PLAINMESSAGE = 1;
				var ERRORMESSAGE = 0;
				var WARNINGMESSAGE = 2;
				var QUESTIONMESSAGE = 3;


				var DEEPLURL = "https://api.deepl.com/v2/translate"
				var DEEPLURL_usage = "https://api.deepl.com/v2/usage"

				function fullmessage(msg,type) {
					Java.type("javax.swing.JOptionPane").showMessageDialog(null
					, msg,'ODM-Translation', type);
				}

				function error(msg) {
					fullmessage(msg,ERRORMESSAGE);
					}
				function message(msg) {
					fullmessage(msg,PLAINMESSAGE);
					}

					function getCurrentLang() {return gParams[CURRENTLANG];}
